import numpy as np
from scipy.spatial.transform import Rotation as Rot
from scipy.optimize import least_squares

def trans(v):
    T=np.eye(4);T[:3,3]=v;return T

def rot(axis,angle):
    T=np.eye(4); T[:3,:3]=Rot.from_rotvec(np.array(axis)*angle).as_matrix();return T

def fk(q,offset=0.107):
    T=trans([0,-.4,.78])@rot([0,0,1],np.pi/2)
    orig=[([0,0,.333],0),([0,0,0],-np.pi/2),([0,-.316,0],np.pi/2),([.0825,0,0],np.pi/2),([-.0825,.384,0],-np.pi/2),([0,0,0],np.pi/2),([.088,0,0],np.pi/2)]
    for a,(p,rx) in zip(q,orig):T=T@trans(p)@rot([1,0,0],rx)@rot([0,0,1],a)
    return T@trans([0,0,offset])@rot([0,0,1],-np.pi/4)

LIMITS=np.array([[-2.8973,2.8973],[-1.7628,1.7628],[-2.8973,2.8973],[-3.0718,-.0698],[-2.8973,2.8973],[-.0175,3.7525],[-2.8973,2.8973]])
def ik(pos,R,q):
    q=np.clip(q,LIMITS[:,0]+1e-6,LIMITS[:,1]-1e-6)
    def fun(a):
        T=fk(a)
        return np.r_[(T[:3,3]-pos)*5,Rot.from_matrix(R@T[:3,:3].T).as_rotvec(),(a-q)*.003]
    o=least_squares(fun,q,bounds=(LIMITS[:,0],LIMITS[:,1]),max_nfev=180,xtol=1e-10,ftol=1e-10,gtol=1e-10)
    T=fk(o.x)
    if np.linalg.norm(T[:3,3]-pos)>.005:raise ValueError(f'IK failed {pos} -> {T[:3,3]}')
    return o.x
