"""Single episode controller. All geometry comes from cameras and Panda proprioception.
Usage: python gen.py move X Y Z [yaw] [duration]; grip WIDTH [duration]; obs
Every submitted command is appended to commands.jsonl for reproducibility.
"""
from rcb_client import Robot
import numpy as np
from pathlib import Path
from scipy.spatial.transform import Rotation as Rot
import json,sys,time
from kinematics import fk,ik
OUT=Path('/app/output');OUT.mkdir(exist_ok=True)
r=Robot()

def save(res):
    idx=res.meta['calls'];res.save(OUT/f'obs_{idx:04d}')
    (OUT/'latest.json').write_text(json.dumps(res.meta,indent=2))
    print('observation',idx,'steps',res.meta['control_steps'],'done',res.meta['done'],res.meta['reason'])
    p=res.meta['proprio']['now'];print('joints',np.round(p[:7],5),'fingers',np.round(p[14:16],5),'tcp',np.round(p[16:23],5))
    return res

def obs():return save(r.get_obs(include_depth=True,video='none'))
def send(A,note):
    with (OUT/'commands.jsonl').open('a') as f:f.write(json.dumps({'actions':np.asarray(A).tolist(),'dt':.1,'note':note})+'\n')
    return save(r.submit('joint_position',A,dt=.1,cameras=['forward','left','right','wrist'],video='none',include_depth=True,note=note))

def move(pos,yaw=0,duration=3):
    res=r.get_obs(cameras=[],video='none');m=np.array(res.meta['proprio']['now']);q=m[:7];start=m[16:19];R0=Rot.from_quat(m[19:23][[1,2,3,0]]).as_matrix()
    R=Rot.from_euler('z',yaw).as_matrix()@np.diag([1,-1,-1]);dr=Rot.from_matrix(R@R0.T).as_rotvec()
    n=round(duration/.1);A=[]
    for t in np.linspace(0,1,n):
        t=t*t*(3-2*t);p=start+(np.array(pos)-start)*t;Rt=Rot.from_rotvec(dr*t).as_matrix()@R0
        q=ik(p,Rt,q);A.append(np.r_[q,m[30:32]])
    return send(A,f'move {pos} yaw {yaw}')
def grip(width,duration=1.5):
    res=r.get_obs(cameras=[],video='none');m=np.array(res.meta['proprio']['now']);target=np.r_[m[23:30],width,width]
    return send(np.tile(target,(round(duration/.1),1)),f'grip {width}')

if __name__=='__main__':
    (OUT/'spec.json').write_text(json.dumps(r.spec(),indent=2))
    if sys.argv[1]=='obs':obs()
    elif sys.argv[1]=='move':move([float(x) for x in sys.argv[2:5]],float(sys.argv[5]) if len(sys.argv)>5 else 0,float(sys.argv[6]) if len(sys.argv)>6 else 3)
    elif sys.argv[1]=='grip':grip(float(sys.argv[2]),float(sys.argv[3]) if len(sys.argv)>3 else 1.5)
    elif sys.argv[1]=='replay':
        for line in open(sys.argv[2]):
            c=json.loads(line);res=send(c['actions'],c['note'])
            if res.done:break
